import javax.imageio.*; import javax.imageio.metadata.*; import javax.imageio.stream.*; import java.awt.image.*; import java.io.*; import java.util.*; import org.w3c.dom.*;
public class JpegMetadataParity { static void dump(Node n,String ind,StringBuilder sb){ sb.append(ind).append(n.getNodeName()); NamedNodeMap m=n.getAttributes(); if(m!=null) for(int i=0;i<m.getLength();i++) sb.append(' ').append(m.item(i).getNodeName()).append('=').append(m.item(i).getNodeValue()); if(n instanceof IIOMetadataNode in && in.getUserObject()!=null){ Object u=in.getUserObject(); sb.append(" [uo ").append(u.getClass().getSimpleName()); if(u instanceof byte[] b) sb.append(' ').append(b.length); sb.append(']'); } sb.append('\n'); for(Node c=n.getFirstChild();c!=null;c=c.getNextSibling()) dump(c,ind+" ",sb); }
 static void tree(String label, IIOMetadata md){ System.out.println("## "+label); if(md==null){System.out.println("null");return;} System.out.println("formats "+Arrays.toString(md.getMetadataFormatNames())+" ro="+md.isReadOnly()+" std="+md.isStandardMetadataFormatSupported()+" native="+md.getNativeMetadataFormatName()); for(String f: new String[]{md.getNativeMetadataFormatName(), IIOMetadataFormatImpl.standardMetadataFormatName}){ if(f==null) continue; StringBuilder sb=new StringBuilder(); try{ dump(md.getAsTree(f),"",sb);}catch(Throwable t){sb.append("EXC "+t);} System.out.print(sb); } }
 public static void main(String[] a) throws Exception { ImageWriter w=ImageIO.getImageWritersByFormatName("jpeg").next(); ImageWriteParam p=w.getDefaultWriteParam(); for(int t: new int[]{BufferedImage.TYPE_INT_RGB, BufferedImage.TYPE_BYTE_GRAY}){ ImageTypeSpecifier its=ImageTypeSpecifier.createFromBufferedImageType(t); tree("default image "+t, w.getDefaultImageMetadata(its,p)); } tree("stream", w.getDefaultStreamMetadata(p));
  BufferedImage im=new BufferedImage(16,16,BufferedImage.TYPE_INT_RGB); for(int y=0;y<16;y++)for(int x=0;x<16;x++) im.setRGB(x,y,(x*16)<<16|(y*16)<<8|128); ByteArrayOutputStream bo=new ByteArrayOutputStream(); ImageIO.write(im,"jpeg",bo); ImageReader r=ImageIO.getImageReadersByFormatName("jpeg").next(); r.setInput(ImageIO.createImageInputStream(new ByteArrayInputStream(bo.toByteArray()))); tree("read image", r.getImageMetadata(0)); tree("read stream", r.getStreamMetadata());
  IIOMetadata md=w.getDefaultImageMetadata(ImageTypeSpecifier.createFromBufferedImageType(BufferedImage.TYPE_INT_RGB),p); try{ Node root=md.getAsTree(md.getNativeMetadataFormatName()); IIOMetadataNode com=new IIOMetadataNode("com"); com.setAttribute("comment","hi"); ((IIOMetadataNode)root.getLastChild()).insertBefore(com, root.getLastChild().getFirstChild()); md.setFromTree(md.getNativeMetadataFormatName(), root); }catch(Throwable t){ System.out.println("setFromTree "+t);} 
  bo=new ByteArrayOutputStream(); ImageOutputStream os=ImageIO.createImageOutputStream(bo); w.setOutput(os); try{ w.write(null,new IIOImage(im,null,md),p);}catch(Throwable t){System.out.println("write "+t);} os.close(); byte[] b=bo.toByteArray(); System.out.println("len "+b.length+" crc "+java.util.zip.CRC32.class.getSimpleName()); java.util.zip.CRC32 c=new java.util.zip.CRC32(); c.update(b); System.out.println(Long.toHexString(c.getValue())); StringBuilder hx=new StringBuilder(); for(int i=0;i<Math.min(b.length,40);i++) hx.append(String.format("%02x",b[i])); System.out.println(hx); } }
